const e=[{title:"Support Vector Machine (SVM): Core Idea",body:"SVM is a supervised method that finds the best separating boundary (hyperplane) between classes.",bullets:[{text:"It maximizes the margin between classes.",icon:"svm"},{text:"Only support vectors (closest points) determine the boundary.",icon:"embedding"},{text:"A larger margin usually improves generalization.",icon:"svm"}],imageUrls:["https://upload.wikimedia.org/wikipedia/commons/f/fd/SVM_margins.png"],speakerNote:"Summarize the body paragraph, then expand each bullet. Land: It maximizes the margin between classes. · Only support vectors (closest points) determine the boundary.. Budget ~2 min. Quick check: ask one volunteer to paraphrase the first bullet.",titleIcon:"svm",conceptAnimation:"svm-margin"},{title:"How SVM Classification Works",bullets:[{text:"New points are classified by the side of the hyperplane they fall on.",icon:"classification"},{text:"Hard margin: no misclassification allowed (strict separation).",icon:"classification"},{text:"Soft margin: allows violations for better robustness with overlap/noise.",icon:"svm"}],formula:"f(x)=w^Tx+b,\\quad \\hat{y}=\\operatorname{sign}(f(x))",note:"Soft-margin SVM adds penalty C to control margin-violation tradeoff.",speakerNote:"Soft-margin SVM adds penalty C to control margin-violation tradeoff.",titleIcon:"classification",conceptAnimation:"svm-margin"},{title:"Why SVM Is Powerful",table:{headers:["Capability","Why It Matters"],rows:[["Maximum-margin principle","Better robustness to small perturbations."],["Kernel support","Handles non-linear class boundaries."],["High-dimensional performance","Works well in text and sparse feature spaces."]]},bullets:[{text:"Common in text classification and image-related features.",icon:"classification"},{text:"Often effective on small-to-medium datasets.",icon:"data"}],speakerNote:"Use the table as your agenda — roughly one row per minute. Land: Common in text classification and image-related features. · Often effective on small-to-medium datasets.. Budget ~3 min. Quick check: ask one volunteer to paraphrase the first bullet.",titleIcon:"svm",conceptAnimation:"svm-margin"},{title:"Kernel Trick: From Non-Linear to Linear Separation",body:"When data is not linearly separable in original space, SVM uses kernel functions to separate it in a transformed feature space.",bullets:[{text:"Avoids explicit high-dimensional mapping in many cases.",icon:"pca"},{text:"Computes similarity using kernel function K(x_i, x_j).",icon:"svm"}],imageUrls:["https://upload.wikimedia.org/wikipedia/commons/f/fe/Kernel_Machine.svg","https://upload.wikimedia.org/wikipedia/commons/5/57/Nonlinear_SVM_example_illustration.svg"],speakerNote:"Summarize the body paragraph, then expand each bullet. Land: Avoids explicit high-dimensional mapping in many cases. · Computes similarity using kernel function K(x_i, x_j).. Budget ~90 sec. Challenge: link this slide to the section opener in one sentence.",titleIcon:"svm"},{title:"RBF Kernel in SVM",formula:"K(x,l_i)=\\exp\\left(-\\frac{\\|x-l_i\\|^2}{2\\sigma^2}\\right)",bullets:[{text:"If x is close to landmark l_i, similarity is near 1.",icon:"svm"},{text:"If x is far, similarity approaches 0.",icon:"svm"},{text:"RBF is a common default for non-linear SVM.",icon:"regression"}],sections:[{heading:"Effect of sigma",bullets:[{text:"Large sigma: smoother, wider decision boundary (higher bias).",icon:"svm"},{text:"Small sigma: tighter, complex boundary (higher variance/overfitting risk).",icon:"warning"}]}],speakerNote:"Walk the on-screen bullets top to bottom. Land: If x is close to landmark l_i, similarity is near 1. · If x is far, similarity approaches 0.. Budget ~2 min. Quick check: ask one volunteer to paraphrase the first bullet.",titleIcon:"svm",conceptAnimation:"svm-margin"},{title:"Common SVM Kernels",table:{headers:["Kernel","Typical Use","Notes"],rows:[["Linear","High-dimensional sparse data","Fast and interpretable margin."],["RBF (Gaussian)","General non-linear patterns","Strong baseline in many tasks."],["Polynomial","Polynomial-like interactions","Degree controls complexity."],["Sigmoid","Neural-style boundary behavior","Less common in practice."]]},speakerNote:"Use the table as your agenda — roughly one row per minute. Anchor on the diagram or table before moving on. Budget ~3 min. Quick check: ask one volunteer to paraphrase the first bullet.",titleIcon:"svm",conceptAnimation:"svm-margin"},{title:"When to Use SVM / When Not",sections:[{heading:"Use SVM When",bullets:[{text:"Data is high-dimensional or moderately sized.",icon:"pca"},{text:"Classes are reasonably separable.",icon:"svm"},{text:"You need non-linear boundaries via kernels.",icon:"regression"}]},{heading:"Avoid SVM When",bullets:[{text:"Dataset is very large (training can be expensive).",icon:"train"},{text:"Data is extremely noisy with weak class structure.",icon:"data"},{text:"Feature count and sample size make kernel matrix too costly.",icon:"svm"}]}],speakerNote:"Walk the on-screen bullets top to bottom. Land: Use: medium-sized data, clear margin, high-dimensional text. · Avoid: massive datasets, heavy noise without kernel tuning.. Budget ~2 min. Poll the room: who has used this in production? Invite one short story.",titleIcon:"svm",conceptAnimation:"svm-margin",bullets:[{text:"Use: medium-sized data, clear margin, high-dimensional text.",icon:"check"},{text:"Avoid: massive datasets, heavy noise without kernel tuning.",icon:"warning"}]},{title:"SVM vs Logistic Regression vs K-NN",table:{headers:["Aspect","SVM","Logistic Regression","K-NN"],rows:[["Primary task","Classification (and SVR)","Classification","Classification"],["Non-linearity","Yes, with kernels","Limited in linear form","Yes (distance-based)"],["Compute profile","Can be heavy on large data","Usually efficient","Heavy at prediction"],["Best for","Complex margins, high-dimensional spaces","Fast interpretable baseline","Local neighborhood patterns"]]},note:"Model choice should be validated with cross-validation and error tradeoff metrics.",speakerNote:"Model choice should be validated with cross-validation and error tradeoff metrics.",titleIcon:"regression",conceptAnimation:"sigmoid-threshold"},{title:"SVM Practical Hyperparameters",table:{headers:["Parameter","Role","Typical Tuning Direction"],rows:[["C","Penalty for margin violations","Higher C -> stricter fit, lower C -> smoother margin"],["Kernel","Similarity function","Start with RBF, compare with linear/polynomial"],["gamma (RBF)","Locality of influence","Higher gamma -> tighter boundary"],["degree (poly)","Polynomial complexity","Increase only when needed"]]},note:"Scale features before SVM, especially for RBF/polynomial kernels.",speakerNote:"Scale features before SVM, especially for RBF/polynomial kernels.",titleIcon:"svm",conceptAnimation:"svm-margin"}];export{e as slides};
